using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
using YJack;

namespace YJack.Tests.SceneLayer.WeatherSystem
{
    public class WeatherPresetTests
    {
        private GameObject _root;
        private FictionalTimeTracker _tracker;
        private WeatherPresetApplicator _applicator;
        private Light _sunLight;
        private WindZone _windZone;
        private GameObject _rainTarget;
        private WeatherPreset _preset;
        private Color _ambientLight;
        private bool _fogEnabled;
        private Color _fogColor;
        private float _fogDensity;
        private FogMode _fogMode;
        private float _fogStartDistance;
        private float _fogEndDistance;

        [SetUp]
        public void SetUp()
        {
            _ambientLight = RenderSettings.ambientLight;
            _fogEnabled = RenderSettings.fog;
            _fogColor = RenderSettings.fogColor;
            _fogDensity = RenderSettings.fogDensity;
            _fogMode = RenderSettings.fogMode;
            _fogStartDistance = RenderSettings.fogStartDistance;
            _fogEndDistance = RenderSettings.fogEndDistance;

            _root = new GameObject("WeatherPresetTests");
            _tracker = _root.AddComponent<FictionalTimeTracker>();
            _applicator = _root.AddComponent<WeatherPresetApplicator>();
            _sunLight = _root.AddComponent<Light>();
            _windZone = _root.AddComponent<WindZone>();
            _rainTarget = new GameObject("RainFx");
            _rainTarget.SetActive(false);

            _applicator.timeTracker = _tracker;
            _applicator.sunLight = _sunLight;
            _applicator.windZone = _windZone;
            _applicator.effectBindings.Add(new WeatherEffectBinding
            {
                effectId = "Rain",
                toggleTarget = _rainTarget
            });

            _preset = ScriptableObject.CreateInstance<WeatherPreset>();
        }

        [TearDown]
        public void TearDown()
        {
            RenderSettings.ambientLight = _ambientLight;
            RenderSettings.fog = _fogEnabled;
            RenderSettings.fogColor = _fogColor;
            RenderSettings.fogDensity = _fogDensity;
            RenderSettings.fogMode = _fogMode;
            RenderSettings.fogStartDistance = _fogStartDistance;
            RenderSettings.fogEndDistance = _fogEndDistance;

            if (_preset != null)
                Object.DestroyImmediate(_preset);

            if (_rainTarget != null)
                Object.DestroyImmediate(_rainTarget);

            if (_root != null)
                Object.DestroyImmediate(_root);
        }

        [Test]
        public void WeatherPresetApplicator_ImplementsIYJackSubsystem()
        {
            Assert.IsInstanceOf<IYJackSubsystem>(_applicator);
        }

        [Test]
        public void Resolve_PartialPreset_OnlyOverridesEnabledSections()
        {
            var fallback = new WeatherRuntimeState
            {
                timeOfDayHours = 8f,
                ambientLight = Color.gray,
                sunColor = Color.white,
                sunIntensity = 1f,
                sunEulerAngles = new Vector3(30f, 45f, 0f),
                fogEnabled = false,
                fogColor = Color.clear,
                fogDensity = 0.01f,
                fogMode = FogMode.Linear,
                fogStartDistance = 10f,
                fogEndDistance = 200f,
                windMain = 3f,
                windTurbulence = 2f,
                windPulseMagnitude = 1f,
                windPulseFrequency = 0.5f,
                effects = new List<WeatherEffectState>
                {
                    new WeatherEffectState("Rain", false, 0.2f),
                    new WeatherEffectState("FogFx", false, 0.4f)
                }
            };

            _preset.timeOfDay.enabled = true;
            _preset.timeOfDay.hourOfDay = 18f;
            _preset.fog.enabled = true;
            _preset.fog.fogEnabled = true;
            _preset.fog.fogColor = Color.blue;
            _preset.fog.fogDensity = 0.08f;
            _preset.fog.fogMode = FogMode.Exponential;
            _preset.fog.fogStartDistance = 0f;
            _preset.fog.fogEndDistance = 100f;
            _preset.effects.Add(new WeatherEffectOverride
            {
                effectId = "Rain",
                enabled = true,
                audioVolume = 0.9f
            });

            var resolved = WeatherPresetRuntime.Resolve(fallback, _preset);

            Assert.AreEqual(18f, resolved.timeOfDayHours);
            Assert.AreEqual(fallback.ambientLight, resolved.ambientLight);
            Assert.AreEqual(fallback.windMain, resolved.windMain);
            Assert.IsTrue(resolved.fogEnabled);
            Assert.AreEqual(Color.blue, resolved.fogColor);
            Assert.IsTrue(resolved.TryGetEffect("Rain", out var rainEffect));
            Assert.IsTrue(rainEffect.enabled);
            Assert.AreEqual(0.9f, rainEffect.audioVolume);
            Assert.IsTrue(resolved.TryGetEffect("FogFx", out var fogEffect));
            Assert.IsFalse(fogEffect.enabled);
        }

        [Test]
        public void Lerp_InterpolatesAcrossMidnightAndUsesTargetEffects()
        {
            var from = new WeatherRuntimeState
            {
                timeOfDayHours = 23f,
                ambientLight = Color.black,
                sunColor = Color.red,
                sunIntensity = 0.25f,
                sunEulerAngles = Vector3.zero,
                fogEnabled = false,
                fogColor = Color.black,
                fogDensity = 0.01f,
                fogMode = FogMode.Linear,
                fogStartDistance = 0f,
                fogEndDistance = 50f,
                windMain = 0f,
                windTurbulence = 0f,
                windPulseMagnitude = 0f,
                windPulseFrequency = 0f,
                effects = new List<WeatherEffectState>
                {
                    new WeatherEffectState("Rain", false, 0f)
                }
            };

            var to = new WeatherRuntimeState
            {
                timeOfDayHours = 1f,
                ambientLight = Color.white,
                sunColor = Color.yellow,
                sunIntensity = 1.25f,
                sunEulerAngles = new Vector3(45f, 90f, 0f),
                fogEnabled = true,
                fogColor = Color.gray,
                fogDensity = 0.05f,
                fogMode = FogMode.ExponentialSquared,
                fogStartDistance = 5f,
                fogEndDistance = 200f,
                windMain = 2f,
                windTurbulence = 1f,
                windPulseMagnitude = 0.5f,
                windPulseFrequency = 0.25f,
                effects = new List<WeatherEffectState>
                {
                    new WeatherEffectState("Rain", true, 1f)
                }
            };

            var blended = WeatherPresetRuntime.Lerp(from, to, 0.5f);

            Assert.That(blended.timeOfDayHours, Is.EqualTo(0f).Within(0.1f));
            Assert.That(blended.sunIntensity, Is.EqualTo(0.75f).Within(0.001f));
            Assert.AreEqual(Color.Lerp(Color.black, Color.white, 0.5f), blended.ambientLight);
            Assert.IsTrue(blended.TryGetEffect("Rain", out var rainEffect));
            Assert.IsTrue(rainEffect.enabled);
        }

        [Test]
        public void ApplyPresetImmediate_UpdatesSceneWeatherAndLeavesUnspecifiedWindUntouched()
        {
            _tracker.SetCurrentHourOfDay(8f);
            _windZone.windMain = 4f;
            _windZone.windTurbulence = 2f;
            _sunLight.color = Color.white;
            _sunLight.intensity = 1f;
            RenderSettings.ambientLight = Color.gray;
            RenderSettings.fog = false;

            _preset.timeOfDay.enabled = true;
            _preset.timeOfDay.hourOfDay = 16f;
            _preset.lighting.enabled = true;
            _preset.lighting.ambientLight = Color.magenta;
            _preset.lighting.sunColor = Color.yellow;
            _preset.lighting.sunIntensity = 2f;
            _preset.lighting.sunEulerAngles = new Vector3(20f, 120f, 0f);
            _preset.fog.enabled = true;
            _preset.fog.fogEnabled = true;
            _preset.fog.fogColor = Color.cyan;
            _preset.fog.fogDensity = 0.04f;
            _preset.fog.fogMode = FogMode.Exponential;
            _preset.fog.fogStartDistance = 5f;
            _preset.fog.fogEndDistance = 150f;
            _preset.effects.Add(new WeatherEffectOverride
            {
                effectId = "Rain",
                enabled = true,
                audioVolume = 1f
            });

            _applicator.ApplyPresetImmediate(_preset);

            Assert.That(_tracker.CurrentHourOfDay, Is.EqualTo(16f).Within(0.1f));
            Assert.AreEqual(Color.magenta, RenderSettings.ambientLight);
            Assert.IsTrue(RenderSettings.fog);
            Assert.AreEqual(Color.cyan, RenderSettings.fogColor);
            Assert.AreEqual(0.04f, RenderSettings.fogDensity);
            Assert.AreEqual(Color.yellow, _sunLight.color);
            Assert.AreEqual(2f, _sunLight.intensity);
            Assert.That(_sunLight.transform.rotation.eulerAngles.x, Is.EqualTo(20f).Within(0.1f));
            Assert.AreEqual(4f, _windZone.windMain);
            Assert.AreEqual(2f, _windZone.windTurbulence);
            Assert.IsTrue(_rainTarget.activeSelf);
        }

        [Test]
        public void ApplyPresetImmediate_WithTimeOverrideDisabled_PreservesTrackerProgression()
        {
            _tracker.SetCurrentHourOfDay(9f);
            _preset.timeOfDay.enabled = false;
            _preset.lighting.enabled = true;
            _preset.lighting.ambientLight = Color.green;

            _applicator.ApplyPresetImmediate(_preset);

            Assert.That(_tracker.CurrentHourOfDay, Is.EqualTo(9f).Within(0.1f));
            Assert.AreEqual(Color.green, RenderSettings.ambientLight);
        }

        [Test]
        public void EffectBinding_ApplyWithToggleStatesDisabled_UpdatesAudioVolumeButPreservesToggleState()
        {
            var audioObject = new GameObject("WeatherAudio");
            var audioSource = audioObject.AddComponent<AudioSource>();
            audioSource.playOnAwake = false;
            audioSource.volume = 0.35f;
            _rainTarget.SetActive(false);

            try
            {
                var binding = new WeatherEffectBinding
                {
                    effectId = "Rain",
                    toggleTarget = _rainTarget,
                    audioSource = audioSource
                };

                binding.Apply(new WeatherEffectState("Rain", true, 1f), true);

                Assert.AreEqual(1f, audioSource.volume);
                Assert.IsFalse(audioSource.isPlaying);
                Assert.IsFalse(_rainTarget.activeSelf);
            }
            finally
            {
                Object.DestroyImmediate(audioObject);
            }
        }
    }
}

