                ambientLight = Color.gray,
                sunColor = Color.white,
                sunIntensity = 1f,
                sunEulerAngles = new Vector3(30f, 45f, 0f),
                fogEnabled = false,
                fogColor = Color.clear,
                fogDensity = 0.01f,
